type Commande {
  id: ID!
  montant: Int!
  client: Client!
  lignes(premieres: Int = 10): [Ligne!]!
}

type Query {
  commande(id: ID!): Commande
}

query {
  commande(id: "42") {
    id
    montant
    client { nom }
  }
}

const chargeurClients = new DataLoader(async (ids) => {
  const clients = await db.clients.trouverParIds(ids);
  return ids.map((id) => clients.find((c) => c.id === id));
});
const resolvers = {
  Commande: {
    client: (commande) => chargeurClients.load(commande.clientId),
  },
};

